void setup() {
  // Настраиваем пин встроенного светодиода как выход
  pinMode(LED_BUILTIN, OUTPUT);
}

void loop() {
  // Включаем светодиод (подаём высокий уровень напряжения)
  digitalWrite(LED_BUILTIN, HIGH);
  // Ждём 1 секунду
  delay(1000);

  // Выключаем светодиод (подаём низкий уровень напряжения)
  digitalWrite(LED_BUILTIN, LOW);
  // Ждём ещё 1 секунду
  delay(1000);
}
